<section class="card"><h2>Open re-assessment marks entry</h2><p>Only Exam Cell and Admin can open or close entry dates. Times use Bhutan time. Tutors can create, save and submit re-assessment records only while their matching window is open.</p><form method="post"><?php csrf();?><input type="hidden" name="action" value="ac_window_create"><div class="form-grid"><?php $v=$_POST?:['academic_year'=>date('Y').'-'.((int)date('Y')+1),'semester'=>'I'];acField('title','Window name (e.g. Autumn re-assessment)',$v);acField('academic_year','Academic year',$v);acField('semester','Semester',$v,['I','II']);acField('programme','Programme (blank = all)',$v,examProgrammes(),'text',false);acField('opens_at','Opens (Bhutan time)',$v,[],'datetime-local');acField('closes_at','Closes (Bhutan time)',$v,[],'datetime-local');?></div><button>Create entry window</button></form></section>
<section class="card"><h2>Entry windows</h2><div class="table-wrap"><table><thead><tr><th>Window</th><th>Applies to</th><th>Opens / closes</th><th>State</th><th></th></tr></thead><tbody><?php foreach(all('SELECT * FROM academic_reassessment_windows ORDER BY id DESC')as $w):?><tr><td><?=e($w['title'])?></td><td><?=e($w['academic_year'].' · Semester '.$w['semester'])?><small><?=e($w['programme']?:'All programmes')?></small></td><td><?=e($w['opens_at'])?><small>to <?=e($w['closes_at'])?></small></td><td><?=!$w['enabled']?'Disabled':($w['opens_at']>now()?'Scheduled':($w['closes_at']<now()?'Closed':'Open'))?></td><td><form method="post"><?php csrf();?><input type="hidden" name="action" value="ac_window_toggle"><input type="hidden" name="window_id" value="<?=$w['id']?>"><input type="hidden" name="enabled" value="<?=$w['enabled']?'0':'1'?>"><button class="secondary"><?=$w['enabled']?'Disable':'Enable'?></button></form></td></tr><?php endforeach;?></tbody></table></div><p class="muted">Disabling a window stops further entry without deleting submitted marks or draft records. Re-enabling does not change its dates.</p></section>
<section class="card"><h2>Expected modules for re-assessment eligibility</h2><p>List every module for the cohort. The system waits for all original module marks before counting failures: 1–2 allows re-assessment, 3 or more means Repeat semester. Do not omit a module to bypass this rule.</p><form method="post"><?php csrf();?><input type="hidden" name="action" value="ac_cohort_save"><div class="form-grid"><?php $v=$_POST?:['academic_year'=>date('Y').'-'.((int)date('Y')+1),'section'=>'A','semester'=>'I','study_year'=>'I'];acField('programme','Programme',$v,examProgrammes());acField('academic_year','Academic year',$v);acField('study_year','Year',$v,['I','II','III','IV']);acField('semester','Semester',$v,['I','II']);acField('section','Section',$v);acField('module_codes','Expected module codes (comma separated)',$v);?></div><button>Save expected modules</button></form><div class="table-wrap"><table><thead><tr><th>Cohort</th><th>Expected modules</th><th>Updated</th></tr></thead><tbody><?php foreach(all('SELECT * FROM academic_cohorts ORDER BY academic_year DESC,programme')as $cohort):?><tr><td><?=e($cohort['programme'].' · '.$cohort['academic_year'].' · Year '.$cohort['study_year'].' · Sem '.$cohort['semester'].' · '.$cohort['section'])?></td><td><?=e(implode(', ',acDecode($cohort['module_codes'])))?></td><td><?=e($cohort['updated_at'])?></td></tr><?php endforeach;?></tbody></table></div></section>
